'use strict'
const test=require('node:test'),assert=require('node:assert/strict'),{compileMessageSchema}=require('../src/protocol/message-schema')
// Independent fixed wire vector, not generated by the compiler under test.
// New composition after the implementation: nested branch + ref/list + UUID +
// signed 64-bit beyond JS safe integer + optional UTF. No new extraction rule.
test('held-out schema composition consumes an independent fixed wire vector',()=>{
  const plan={schema:'mineflayer-mod-support/codec-ir/v1',definitions:{Entry:{type:'struct',fields:[{name:'key',codec:{type:'resource_location'}},{name:'amount',codec:{type:'long'}}]}},root:{type:'struct',fields:[
    {name:'sequence',codec:{type:'int'}},{name:'action',codec:{type:'enum',ordinalType:'varint',values:['read','write']}},
    {name:'body',codec:{type:'switch',field:'action',cases:{read:{type:'struct',fields:[]},write:{type:'struct',fields:[{name:'target',codec:{type:'uuid'}},{name:'entries',codec:{type:'list',lengthType:'byte',maxItems:4,element:{type:'ref',name:'Entry'}}},{name:'note',codec:{type:'optional',value:{type:'utf'}}}]}}}}
  ]}}
  const vector=Buffer.from('0000002a0100112233445566778899aabbccddeeff0203783a61002000000000000103783a62ffffffffffffffff01026f6b','hex'),codec=compileMessageSchema(plan),value=codec.decode(vector)
  assert.equal(value.sequence,42);assert.equal(value.body.entries[0].amount,9007199254740993n);assert.equal(value.body.entries[1].amount,-1n);assert.equal(value.body.target,'00112233-4455-6677-8899-aabbccddeeff');assert.equal(value.body.note,'ok');assert.deepEqual(codec.encode(value),vector)
})
